const body = $input.first().json.body || $input.first().json;
const dp = body.discovery_packet || {};
const summary = body.summary || 'Discovery complete';

return {
  summary,
  company: dp.company_name || 'Unknown',
  contact: dp.contact_name || 'Unknown',
  email: dp.contact_email || 'Unknown',
  business_type: dp.business_type || 'Unknown',
  primary_goal: dp.primary_goal || 'Unknown',
  service_interest: dp.service_interest || 'Unknown',
  budget_band: dp.budget_band || 'Unknown',
  urgency_score: dp.urgency_score || 'N/A',
  fit_score: dp.fit_score || 'N/A',
  unknowns: (dp.unknowns || []).join(', ') || 'None',
  open_questions: (body.open_questions || []).join('\n') || 'None',
  next_agent: body.recommended_next_agent || 'None',
  run_id: body.run_id || null,
  lead_id: body.lead_id || null
};
